css:
.chapter-container {
  --ink: #2d3748;
  --muted: #718096;
  --accent: #2C5282;
  --warm: #DD6B20;
  --line: #e2e8f0;
  --paper: #f7fafc;

  font-family: system-ui, -apple-system, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--ink);
  background-color: var(--paper);
  padding: 2rem;
  max-width: 1200px;
  margin: 0 auto;
  border: 1px solid var(--line);
}

.chapter-header {
  margin-bottom: 2rem;
  border-bottom: 2px solid var(--accent);
  padding-bottom: 1rem;
}

.chapter-title {
  font-size: 2rem;
  color: var(--accent);
  margin: 0 0 0.5rem 0;
}

.chapter-intro {
  color: var(--muted);
  font-size: 1rem;
  margin: 0;
}

.content-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  margin-bottom: 3rem;
}

@media (max-width: 768px) {
  .content-grid {
    grid-template-columns: 1fr;
  }
}

.section-heading {
  font-size: 1.25rem;
  color: var(--accent);
  margin-bottom: 1rem;
  border-left: 4px solid var(--accent);
  padding-left: 0.5rem;
}

.text-block {
  margin-bottom: 1rem;
  font-size: 0.95rem;
}

.highlight-warning {
  color: var(--warm);
  font-weight: bold;
  background: rgba(221, 107, 32, 0.1);
  padding: 0 0.25rem;
}

.source-box {
  margin-top: 1.5rem;
  padding: 1rem;
  background: #edf2f7;
  border-radius: 4px;
}

.source-label {
  font-size: 0.85rem;
  color: var(--muted);
  margin-bottom: 0.5rem;
}

.source-btn {
  background: white;
  border: 1px solid var(--line);
  padding: 0.5rem 1rem;
  font-size: 0.85rem;
  cursor: pointer;
  margin-right: 0.5rem;
  color: var(--ink);
}

.source-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.control-group {
  margin-bottom: 1.5rem;
}

.control-label {
  display: block;
  font-size: 0.9rem;
  margin-bottom: 0.5rem;
  color: var(--ink);
}

.task-select {
  width: 100%;
  padding: 0.5rem;
  font-size: 1rem;
  border: 1px solid var(--line);
  background: white;
  color: var(--ink);
}

.chart-container {
  background: white;
  border: 1px solid var(--line);
  padding: 1.5rem;
  margin-bottom: 1.5rem;
  min-height: 250px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}

.chart-bars {
  display: flex;
  align-items: flex-end;
  justify-content: space-around;
  height: 200px;
  gap: 1rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--line);
}

.chart-bar {
  width: 40px;
  background: var(--accent);
  transition: height 0.3s ease;
  position: relative;
  min-height: 2px;
}

.chart-bar.warning {
  background: var(--warm);
}

.chart-bar-label {
  position: absolute;
  bottom: -25px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 0.75rem;
  white-space: nowrap;
  color: var(--muted);
}

.chart-bar-value {
  position: absolute;
  top: -20px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 0.75rem;
  font-weight: bold;
  color: var(--ink);
}

.chart-legend {
  margin-top: 1rem;
  font-size: 0.85rem;
  color: var(--muted);
}

.chart-note {
  font-size: 0.85rem;
  color: var(--muted);
  font-style: italic;
}

.cost-analysis-section {
  border-top: 2px solid var(--line);
  padding-top: 2rem;
}

.cost-chart .chart-bar {
  background: #48bb78;
}

.cost-ratio-display {
  background: #edf2f7;
  padding: 1rem;
  margin-bottom: 1rem;
  font-size: 0.9rem;
}

.ratio-value {
  font-weight: bold;
  color: var(--accent);
}

.reset-btn {
  background: var(--ink);
  color: white;
  border: none;
  padding: 0.75rem 1.5rem;
  font-size: 0.9rem;
  cursor: pointer;
}

.reset-btn:hover {
  opacity: 0.9;
}

@media (prefers-reduced-motion: reduce) {
  .chart-bar {
    transition: none;
  }
}

javascript:
(function() {
  'use strict';

  // 数据解析辅助函数
  function parseScientific(str) {
    if (str === null || str === undefined || str === '') return null;
    const num = Number(str);
    return isNaN(num) ? null : num;
  }

  // 获取表格数据
  function getTableData() {
    if (!window.paperMindData || !window.paperMindData.tables) {
      console.warn('paperMindData not available');
      return null;
    }
    const table = window.paperMindData.tables.find(t => t.id === 'p8-Table_2');
    return table || null;
  }

  // 渲染 BLEU 图表
  function renderBleuChart(task) {
    const table = getTableData();
    if (!table) return;

    const container = document.querySelector('#result-chart .chart-bars');
    const legend = document.querySelector('#result-chart .chart-legend');
    if (!container) return;

    container.innerHTML = '';
    legend.innerHTML = '';

    const colKey = task === 'ende' ? 'BLEU EN-DE' : 'BLEU EN-FR';
    const models = [
      { id: 'row_10', label: 'Transformer (big)', warning: task === 'enfr' },
      { id: 'row_7', label: 'GNMT+RL Ens' },
      { id: 'row_8', label: 'ConvS2S Ens' },
      { id: 'row_5', label: 'MoE' }
    ];

    let maxVal = 0;
    const dataPoints = [];

    models.forEach(m => {
      const row = table.rows.find(r => r.id === m.id);
      if (row && row.values && row.values[colKey] !== null) {
        const val = parseScientific(row.values[colKey]);
        if (val !== null) {
          dataPoints.push({ label: m.label, value: val, warning: m.warning });
          if (val > maxVal) maxVal = val;
        }
      }
    });

    // 英法任务特殊处理：添加正文 41.0 对比
    if (task === 'enfr') {
      dataPoints.push({ label: '原文正文', value: 41.0, warning: true, isText: true });
      if (41.0 > maxVal) maxVal = 41.0;
    }

    const scaleFactor = 200 / (maxVal * 1.1); // 留白 10%

    dataPoints.forEach(dp => {
      const bar = document.createElement('div');
      bar.className = 'chart-bar' + (dp.warning ? ' warning' : '');
      bar.setAttribute('data-bleu', dp.value);
      bar.setAttribute('data-model', dp.label);

      const height = dp.value * scaleFactor;
      bar.style.height = Math.max(2, height) + 'px';

      const valLabel = document.createElement('span');
      valLabel.className = 'chart-bar-value';
      valLabel.textContent = dp.value;

      const nameLabel = document.createElement('span');
      nameLabel.className = 'chart-bar-label';
      nameLabel.textContent = dp.label;

      bar.appendChild(valLabel);
      bar.appendChild(nameLabel);
      container.appendChild(bar);
    });

    legend.textContent = '数据源自 Table 2 (p8-Table_2)。英法任务高亮显示正文与表格差异。';
  }

  // 渲染成本图表
  function renderCostChart() {
    const table = getTableData();
    if (!table) return;

    const container = document.querySelector('#cost-chart .chart-bars');
    const ratioOutput = document.getElementById('cost-ratio-output');
    if (!container) return;

    container.innerHTML = '';
    if (ratioOutput) ratioOutput.innerHTML = '';

    // Transformer big cost
    const transRow = table.rows.find(r => r.id === 'row_10');
    const transCostStr = transRow ? transRow.values['Merged cost FLOPs'] : null;
    const transCost = parseScientific(transCostStr);

    if (transCost === null) {
      container.innerHTML = '<p>成本数据缺失</p>';
      return;
    }

    const competitors = [
      { id: 'row_7', label: 'GNMT+RL Ens', col: 'Cost EN-FR FLOPs' },
      { id: 'row_5', label: 'MoE', col: 'Cost EN-FR FLOPs' }
    ];

    let maxVal = transCost;
    const dataPoints = [{ label: 'Transformer', value: transCost }];

    competitors.forEach(c => {
      const row = table.rows.find(r => r.id === c.id);
      if (row && row.values && row.values[c.col] !== null) {
        const val = parseScientific(row.values[c.col]);
        if (val !== null) {
          dataPoints.push({ label: c.label, value: val });
          if (val > maxVal) maxVal = val;
        }
      }
    });

    const scaleFactor = 200 / (maxVal * 1.1);

    dataPoints.forEach(dp => {
      const bar = document.createElement('div');
      bar.className = 'chart-bar';
      const height = dp.value * scaleFactor;
      bar.style.height = Math.max(2, height) + 'px';

      // 科学计数法显示简化
      const displayVal = dp.value.toExponential(1);

      const valLabel = document.createElement('span');
      valLabel.className = 'chart-bar-value';
      valLabel.textContent = displayVal;

      const nameLabel = document.createElement('span');
      nameLabel.className = 'chart-bar-label';
      nameLabel.textContent = dp.label;

      bar.appendChild(valLabel);
      bar.appendChild(nameLabel);
      container.appendChild(bar);
    });

    // 计算比例
    if (ratioOutput) {
      const gnmtRow = table.rows.find(r => r.id === 'row_7');
      const moeRow = table.rows.find(r => r.id === 'row_5');

      let gnmtRatio = '--';
      let moeRatio = '--';

      if (gnmtRow && gnmtRow.values['Cost EN-FR FLOPs']) {
        const gnmtCost = parseScientific(gnmtRow.values['Cost EN-FR FLOPs']);
        if (gnmtCost) {
          const ratio = (1 - (transCost / gnmtCost)) * 100;
          gnmtRatio = ratio.toFixed(1) + '%';
        }
      }

      if (moeRow && moeRow.values['Cost EN-FR FLOPs']) {
        const moeCost = parseScientific(moeRow.values['Cost EN-FR FLOPs']);
        if (moeCost) {
          const ratio = (1 - (transCost / moeCost)) * 100;
          moeRatio = ratio.toFixed(1) + '%';
        }
      }

      ratioOutput.innerHTML = `
        <p>相对于 GNMT+RL Ensemble 成本降低：<span class="ratio-value">${gnmtRatio}</span></p>
        <p>相对于 MoE 成本降低：<span class="ratio-value">${moeRatio}</span></p>
      `;
    }
  }

  // 初始化
  function init() {
    const taskSelect = document.getElementById('result-task');
    const resetBtn = document.getElementById('reset-charts');

    if (taskSelect) {
      taskSelect.addEventListener('change', function(e) {
        renderBleuChart(e.target.value);
      });
      // 初始渲染
      renderBleuChart(taskSelect.value);
    }

    renderCostChart();

    if (resetBtn) {
      resetBtn.addEventListener('click', function() {
        if (taskSelect) taskSelect.value = 'ende';
        renderBleuChart('ende');
        renderCostChart();
      });
    }

    // 来源按钮事件代理
    document.addEventListener('click', function(e) {
      if (e.target.matches('.source-btn')) {
        const sourceId = e.target.getAttribute('data-source');
        // 宿主内核处理桥接，此处仅做视觉反馈或预留接口
        // 实际环境中会触发来源高亮
        e.target.blur();
      }
    });
  }

  // 等待 DOM 就绪
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
